begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('00000000-0000-4000-8000-000000262001','s262-owner@test.invalid');
insert into public.profiles(id,display_name)values('00000000-0000-4000-8000-000000262001','S262 owner');
insert into public.tenants(id,name,slug)values('10000000-0000-4000-8000-000000262001','S262 Engage A','s262-engage-a'),('10000000-0000-4000-8000-000000262002','S262 Engage B','s262-engage-b');
insert into public.tenant_settings(tenant_id)values('10000000-0000-4000-8000-000000262001'),('10000000-0000-4000-8000-000000262002');
insert into public.tenant_memberships(tenant_id,user_id,role)values('10000000-0000-4000-8000-000000262001','00000000-0000-4000-8000-000000262001','tenant_owner');
insert into public.tenant_feature_flags(tenant_id,flag_key,enabled,rollout_reason,changed_by)select id,'engage',true,'S262 isolated option completeness','00000000-0000-4000-8000-000000262001'::uuid from public.tenants where id in('10000000-0000-4000-8000-000000262001','10000000-0000-4000-8000-000000262002');
insert into public.engage_campaigns(id,public_id,tenant_id,kind,status,title,question,result_visibility)
 select ('21000000-0000-4000-8000-'||lpad((262000+n)::text,12,'0'))::uuid,('20000000-0000-4000-8000-'||lpad((262000+n)::text,12,'0'))::uuid,'10000000-0000-4000-8000-000000262001','poll','live','Campagne '||n,'Wie kiezen we?','after_close' from( values(2),(12),(13),(24))counts(n);
insert into public.engage_options(id,tenant_id,campaign_id,label,sort_order)
 select ('30000000-0000-4000-8000-'||lpad((262000000+n*100+i)::text,12,'0'))::uuid,'10000000-0000-4000-8000-000000262001',('21000000-0000-4000-8000-'||lpad((262000+n)::text,12,'0'))::uuid,'Speler '||i,i from(values(2),(12),(13),(24))counts(n)cross join lateral generate_series(1,n)i;
create function pg_temp.engage_doc(p_count integer,p_paged boolean default true)returns jsonb language sql stable as $fn$
 select jsonb_set(jsonb_set($doc${"schemaVersion":1,"artboard":{"width":1920,"height":1080,"orientation":"landscape","background":{"kind":"solid","color":"#FAFAF7"},"safeArea":{"top":64,"right":64,"bottom":64,"left":64}},"motion":{"enabled":true,"durationMs":18000,"fps":30},"elements":[],"syncPresentation":{"schemaVersion":1,"rendererVersion":"sync-v1","sourceRevision":"8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a","family":"engage","orientation":"landscape","theme":"fieldflow","name":"Volledige stemkaart","club":{"name":"S262 Engage A","tagline":""},"title":"Wie kiezen we?","headline":"","body":"","subtitle":"","topLabel":"CLUB TV","footer":"","footerRight":"","rows":[],"rowsPerPage":4,"ownRowIndexes":[],"category":"","subline":"","lineup":[],"news":[],"imageCaption":"","state":"ready","style":{"background":"stadium","backgroundPosition":"center","font":"Inter, sans-serif","fontChanged":false,"accent":"#1763ed","alignment":"left","scale":100,"safeMargin":5,"showLogo":true,"showFooter":true,"motion":"geen"}},"metadata":{"fontRegistryVersion":"2026-09-09.1","tenantBrandApplied":false}}$doc$::jsonb,'{syncPresentation,poll}',jsonb_build_object('id',('20000000-0000-4000-8000-'||lpad((262000+p_count)::text,12,'0')),'title','Wie kiezen we?','status','live','visibility','after_close','options',(select jsonb_agg(jsonb_build_object('id',id,'label',label,'votes',0)order by sort_order,id)from public.engage_options where tenant_id='10000000-0000-4000-8000-000000262001'and campaign_id=('21000000-0000-4000-8000-'||lpad((262000+p_count)::text,12,'0'))::uuid))||case when p_paged then jsonb_build_object('optionsPerPage',4)else '{}'::jsonb end),'{motion}',jsonb_build_object('enabled',p_paged and p_count>4,'durationMs',case when p_paged then ceil(p_count::numeric/4)::integer*3000 else 3000 end,'fps',30));
$fn$;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000262001',true);
select is(private.sync_slide_page_count_v1(pg_temp.engage_doc(n)->'syncPresentation'),ceil(n::numeric/4)::integer,'every paged option is included for count '||n)from(values(2),(12),(13),(24))counts(n);
select is(private.sync_slide_page_count_v1(pg_temp.engage_doc(12,false)->'syncPresentation'),1,'unmarked historical twelve-choice documents retain one-page binary timing');
select is(private.sync_slide_page_count_v1(jsonb_set(pg_temp.engage_doc(24)->'syncPresentation','{poll,optionsPerPage}','4.0'::jsonb)),6,'JSON numeric4.0 keeps the same six-page authority as JavaScript number4');
select lives_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262001','landscape',1920,1080,jsonb_set(pg_temp.engage_doc(24),'{syncPresentation,poll,optionsPerPage}','4.0'::jsonb),'{}')$$,'a valid complete4.0 presentation remains compatible with the canonical number schema');
select throws_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262001','landscape',1920,1080,jsonb_set(jsonb_set(pg_temp.engage_doc(24),'{syncPresentation,poll,optionsPerPage}','4.0'::jsonb),'{motion,durationMs}','3000'),'{}')$$,'23514','Sync document duration invalid','numeric formatting cannot turn a six-page campaign into a three-second export');
select lives_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262001','landscape',1920,1080,pg_temp.engage_doc(12,false),'{}')$$,'historical unmarked document remains valid without a rewrite');
set local role authenticated;
select lives_ok(format($sql$select public.create_studio_project_v1(p_tenant_id=>'10000000-0000-4000-8000-000000262001',p_name=>%L,p_project_kind=>'design',p_orientation=>'landscape',p_document=>pg_temp.engage_doc(%s),p_referenced_asset_ids=>'{}'::uuid[],p_idempotency_key=>%L)$sql$,'S262 paged '||n,n,'40000000-0000-4000-8000-'||lpad((262000+n)::text,12,'0')),'owner creates a complete own campaign with '||n||' answers through the existing writer')from(values(2),(12),(13),(24))counts(n);
select is((select jsonb_array_length(draft.document_json#>'{syncPresentation,poll,options}')from public.studio_project_drafts draft join public.studio_projects project on project.tenant_id=draft.tenant_id and project.id=draft.project_id where project.name='S262 paged 24'),24,'all twenty-four stable option IDs persist through normal authoring');
select throws_ok($$select public.create_studio_project_v1(p_tenant_id=>'10000000-0000-4000-8000-000000262002',p_name=>'Other tenant',p_project_kind=>'design',p_orientation=>'landscape',p_document=>pg_temp.engage_doc(24),p_referenced_asset_ids=>'{}'::uuid[],p_idempotency_key=>'40000000-0000-4000-8000-000000262101')$$,'42501',null,'the paging schema does not broaden cross-tenant writes');
reset role;
select throws_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262002','landscape',1920,1080,pg_temp.engage_doc(24),'{}')$$,'42501',null,'foreign public campaign IDs still fail the tenant binding');
select throws_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262001','landscape',1920,1080,jsonb_set(pg_temp.engage_doc(24),'{syncPresentation,poll,options,23,id}','"30000000-0000-4000-8000-000000262999"'),'{}')$$,'23514',null,'a foreign last-page answer is not silently replaced or discarded');
select throws_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262001','landscape',1920,1080,jsonb_set(pg_temp.engage_doc(24),'{syncPresentation,poll,options,23,votes}','1'),'{}')$$,'23514',null,'private votes are forbidden even on the final page');
select throws_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262001','landscape',1920,1080,jsonb_set(pg_temp.engage_doc(24),'{motion,durationMs}','17999'),'{}')$$,'23514','Sync document duration invalid','every page still requires at least three seconds');
select throws_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262001','landscape',1920,1080,jsonb_set(pg_temp.engage_doc(24),'{motion,enabled}','false'),'{}')$$,'23514','Sync document duration invalid','a multipage campaign cannot be exported as a one-page PNG');
select throws_ok($$select private.assert_studio_document('10000000-0000-4000-8000-000000262001','landscape',1920,1080,jsonb_set(pg_temp.engage_doc(24),'{motion,durationMs}','120001'),'{}')$$,'23514','Sync document duration invalid','the full binary duration remains bounded at 120 seconds');
select throws_ok($$select private.assert_sync_slide_v1('10000000-0000-4000-8000-000000262001',(pg_temp.engage_doc(24)->'syncPresentation')#-'{poll,optionsPerPage}')$$,'23514',null,'thirteen to twenty-four answers require the explicit readable layout');
select throws_ok($$select private.assert_sync_slide_v1('10000000-0000-4000-8000-000000262001',jsonb_set(pg_temp.engage_doc(24)->'syncPresentation','{poll,options}',jsonb_build_array(pg_temp.engage_doc(24)#>'{syncPresentation,poll,options,0}')))$$,'23514',null,'one answer remains invalid');
select throws_ok($$select private.assert_sync_slide_v1('10000000-0000-4000-8000-000000262001',jsonb_set(pg_temp.engage_doc(24)->'syncPresentation','{poll,options}',(pg_temp.engage_doc(24)#>'{syncPresentation,poll,options}')||jsonb_build_array(pg_temp.engage_doc(24)#>'{syncPresentation,poll,options,0}')))$$,'23514',null,'twenty-five answers remain invalid without truncation');
-- A real immutable export keeps every page/ID and the complete verified MP4.
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height,duration_seconds)values('20000000-0000-4000-8000-000000262100','10000000-0000-4000-8000-000000262001','video','Complete Engage export','engage.mp4','video/mp4','ready','tenants/10000000-0000-4000-8000-000000262001/assets/20000000-0000-4000-8000-000000262100/original/engage.mp4',1024,repeat('a',64),1920,1080,18);
insert into public.media_variants(id,tenant_id,asset_id,variant_type,storage_path,mime_type,file_size_bytes,checksum_sha256,width,height,duration_seconds)values('90000000-0000-4000-8000-000000262100','10000000-0000-4000-8000-000000262001','20000000-0000-4000-8000-000000262100','player_1080p','tenants/10000000-0000-4000-8000-000000262001/assets/20000000-0000-4000-8000-000000262100/original/engage.mp4','video/mp4',1024,repeat('a',64),1920,1080,18);
insert into public.studio_revisions(id,tenant_id,project_id,revision_number,draft_revision,document_json,document_hash)select '40000000-0000-4000-8000-000000262100',project.tenant_id,project.id,1,draft.draft_revision,draft.document_json,draft.document_hash from public.studio_projects project join public.studio_project_drafts draft on draft.tenant_id=project.tenant_id and draft.project_id=project.id where project.name='S262 paged 24';
insert into public.studio_render_jobs(id,tenant_id,project_id,revision_id,status,output_kind,request_idempotency_key,request_hash,media_asset_id,progress,finished_at)select '50000000-0000-4000-8000-000000262100',tenant_id,id,'40000000-0000-4000-8000-000000262100','completed','mp4','50000000-0000-4000-8000-000000262101',repeat('d',64),'20000000-0000-4000-8000-000000262100',100,now()from public.studio_projects where name='S262 paged 24';
insert into public.studio_exports(id,tenant_id,project_id,revision_id,render_job_id,media_asset_id,output_kind,width,height,duration_seconds,checksum_sha256)select '60000000-0000-4000-8000-000000262100',tenant_id,id,'40000000-0000-4000-8000-000000262100','50000000-0000-4000-8000-000000262100','20000000-0000-4000-8000-000000262100','mp4',1920,1080,18,repeat('a',64)from public.studio_projects where name='S262 paged 24';
insert into public.playlists(id,tenant_id,name)values('70000000-0000-4000-8000-000000262100','10000000-0000-4000-8000-000000262001','Complete Engage sequence');
insert into public.playlist_releases(id,tenant_id,playlist_id,version,manifest_hash,manifest_json,item_count,total_duration_seconds,total_bytes)values('80000000-0000-4000-8000-000000262100','10000000-0000-4000-8000-000000262001','70000000-0000-4000-8000-000000262100',1,repeat('e',64),'{}',1,18,1024);
create function pg_temp.publish_engage(p_id uuid,p_duration integer default 18,p_trim_start numeric default 0,p_trim_end numeric default null,p_hash text default repeat('a',64))returns void language sql as $fn$
 insert into public.playlist_release_items(id,tenant_id,playlist_id,release_id,media_asset_id,media_variant_id,sort_order,duration_seconds,fit_mode,muted,asset_kind,asset_title,storage_path,mime_type,file_size_bytes,checksum_sha256,trim_start_seconds,trim_end_seconds,engage_campaign_id,engage_public_id,engage_title,engage_question)
 values(p_id,'10000000-0000-4000-8000-000000262001','70000000-0000-4000-8000-000000262100','80000000-0000-4000-8000-000000262100','20000000-0000-4000-8000-000000262100','90000000-0000-4000-8000-000000262100',0,p_duration,'contain',true,'video','Complete Engage export','tenants/10000000-0000-4000-8000-000000262001/assets/20000000-0000-4000-8000-000000262100/original/engage.mp4','video/mp4',1024,p_hash,p_trim_start,p_trim_end,'21000000-0000-4000-8000-000000262024','20000000-0000-4000-8000-000000262024','Campagne 24','Wie kiezen we?');
$fn$;
select lives_ok($$select pg_temp.publish_engage('90000000-0000-4000-8000-000000262101')$$,'the complete six-page MP4 publishes through the unchanged immutable release trigger chain');
select is((select sync_studio_presentation_json#>'{poll,options}'from public.playlist_release_items where id='90000000-0000-4000-8000-000000262101'),pg_temp.engage_doc(24)#>'{syncPresentation,poll,options}','every option ID, order and zero private count is frozen from the immutable export');
select is((select sync_studio_duration_ms from public.playlist_release_items where id='90000000-0000-4000-8000-000000262101'),18000,'all six minimum-three-second pages keep their complete binary duration');
select throws_ok($$select pg_temp.publish_engage('90000000-0000-4000-8000-000000262102',12)$$,'23514','Sync release duration does not cover every saved page','placement duration cannot drop the last two pages');
select throws_ok($$select pg_temp.publish_engage('90000000-0000-4000-8000-000000262103',18,1)$$,'23514','Sync release trim does not cover every saved page','the start of a saved Engage sequence cannot be trimmed away');
select throws_ok($$select pg_temp.publish_engage('90000000-0000-4000-8000-000000262104',18,0,15)$$,'23514','Sync release trim does not cover every saved page','the final four choices cannot be trimmed away');
select throws_ok($$select pg_temp.publish_engage('90000000-0000-4000-8000-000000262105',18,0,null,repeat('f',64))$$,'23514','Studio export checksum does not match the release','a different binary checksum still fails before release activation');
select throws_ok($$update public.playlist_release_items set sync_studio_duration_ms=3000 where id='90000000-0000-4000-8000-000000262101'$$,'23514','playlist releases are immutable','paged Engage does not make saved releases mutable');
set local role authenticated;
select is((select count(*)from public.playlist_release_items where tenant_id='10000000-0000-4000-8000-000000262002'),0::bigint,'owner A still cannot read releases from tenant B');
reset role;
select is(has_function_privilege(role,'private.sync_slide_page_count_v1(jsonb)','execute'),false,'the new private page authority is not exposed to '||role)from(values('anon'),('authenticated'),('service_role'))roles(role);
select is(has_function_privilege('authenticated','private.assert_studio_document(uuid,text,integer,integer,jsonb,uuid[])','execute'),false,'the original Studio validator remains private');
select is(has_function_privilege('authenticated','private.freeze_sync_studio_release_item_v1()','execute'),false,'the original release freeze remains private');
select *from finish();
rollback;
